//! Opaque icon tokens resolved to real system icon files.
//!
//! The HTTP frontend never sees filesystem paths. Tokens are generated by
//! Rust when an icon name resolves to a file under an allowed system icon
//! root; `GET /oziro-icon/<token>` serves exactly those pre-resolved files.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

/// Roots the host may serve icon files from. Absolute `Icon=` paths in
/// untrusted .desktop files are ignored unless they land inside these roots.
fn allowed_icon_roots() -> Vec<PathBuf> {
    let mut roots = vec![
        PathBuf::from("/usr/share/icons"),
        PathBuf::from("/usr/local/share/icons"),
        PathBuf::from("/usr/share/pixmaps"),
        PathBuf::from("/var/lib/flatpak/exports/share/icons"),
    ];

    if let Ok(home) = std::env::var("HOME") {
        let home = PathBuf::from(home);
        roots.push(home.join(".local/share/icons"));
        roots.push(home.join(".icons"));
        roots.push(home.join(".local/share/flatpak/exports/share/icons"));
    }

    roots
}

/// True when a path canonicalizes into one of the allowed icon roots.
pub fn is_allowed_path(path: &Path) -> bool {
    let canonical = match path.canonicalize() {
        Ok(value) => value,
        Err(_) => return false,
    };

    allowed_icon_roots().iter().any(|root| canonical.starts_with(root))
}

/// Maps icon names and file paths to opaque tokens, deduplicating paths.
#[derive(Debug, Default)]
pub struct IconRegistry {
    inner: Mutex<IconRegistryInner>,
}

#[derive(Debug, Default)]
struct IconRegistryInner {
    by_key: HashMap<String, String>,
    files: HashMap<String, PathBuf>,
    counter: u64,
}

impl IconRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    /// Registers an icon by freedesktop icon theme name. Returns a token when
    /// the name resolves to a file inside an allowed root.
    pub fn register_icon_name(&self, name: &str) -> Option<String> {
        if name.trim().is_empty() {
            return None;
        }

        let key = format!("name:{name}");

        if let Some(token) = self.cached(&key) {
            return Some(token);
        }

        let resolved = freedesktop_icons::lookup(name).with_size(64).with_cache().find();

        match resolved {
            Some(path) if is_allowed_path(&path) => Some(self.insert(key, path)),
            _ => None,
        }
    }

    /// Resolves the file backing a token. Only tokens minted by this
    /// registry are returned; unknown tokens are rejected.
    pub fn resolve(&self, token: &str) -> Option<PathBuf> {
        let inner = self.inner.lock().expect("icon registry lock");
        inner.files.get(token).cloned()
    }

    fn cached(&self, key: &str) -> Option<String> {
        let inner = self.inner.lock().expect("icon registry lock");
        inner.by_key.get(key).cloned()
    }

    fn insert(&self, key: String, path: PathBuf) -> String {
        let mut inner = self.inner.lock().expect("icon registry lock");

        if let Some(existing) = inner.by_key.get(&key) {
            return existing.clone();
        }

        inner.counter += 1;
        let token = format!("icn-{:06}", inner.counter);

        inner.by_key.insert(key, token.clone());
        inner.files.insert(token.clone(), path);

        token
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_tokens_are_opaque_and_unique_per_key() {
        let registry = IconRegistry::new();

        let token_a = registry.insert("name:test-a".to_owned(), PathBuf::from("/tmp/a.png"));
        let token_again = registry.cached("name:test-a").expect("cached");
        let token_b = registry.insert("name:test-b".to_owned(), PathBuf::from("/tmp/b.png"));

        assert_eq!(token_a, token_again);
        assert_ne!(token_a, token_b);
        assert!(token_a.starts_with("icn-"));
    }

    #[test]
    fn resolve_rejects_unknown_tokens() {
        let registry = IconRegistry::new();
        assert!(registry.resolve("icn-999999").is_none());
        assert!(registry.resolve("icn-000001").is_none());
        assert!(registry.resolve("/etc/passwd").is_none());
    }

    #[test]
    fn empty_names_are_rejected() {
        let registry = IconRegistry::new();
        assert!(registry.register_icon_name("   ").is_none());
    }

    #[test]
    fn allowed_roots_are_system_directories() {
        let roots = allowed_icon_roots();
        assert!(roots.iter().any(|root| root.ends_with("share/icons")));

        let fake = PathBuf::from("/home/oziro/secret/id_rsa");
        assert!(!is_allowed_path(&fake));
        assert!(!is_allowed_path(&PathBuf::from("/nonexistent/x.png")));
    }
}
